[5461]={name="The Human, Ras Frostwhisper",level=60,req=57,xp=6600,side="B",start={k="npc",n="Magistrate Marduke",m=1422,x=70.6,y=74.1},finish={k="npc",n="Magistrate Marduke",m=1422,x=70.6,y=74.1},preAny={5384},text="Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."},
